const articles = $('Get Top Articles').all().map(i => i.json);
const sponsor = $('Get Sponsor').first()?.json || null;
const fs = require('fs');

let prompt = fs.readFileSync('/prompts/newsletter.md', 'utf8');
prompt = prompt
  .replace('{{date}}', new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }))
  .replace('{{issue_number}}', 'auto')
  .replace('{{newsletter_name}}', process.env.NEWSLETTER_NAME || 'Flora News')
  .replace('{{articles_json}}', JSON.stringify(articles, null, 2))
  .replace('{{sponsor_json}}', JSON.stringify(sponsor, null, 2));

return [{ json: { prompt, articles, sponsor } }];

const item = $input.first().json;
let newsletter;
try { newsletter = JSON.parse(item.choices[0].message.content); } catch(e) { throw new Error('Newsletter JSON parse failed: ' + e.message); }
return [{ json: newsletter }];
